def round_half_to_even(n):
    """
    Round half to even.

    :param n: The number to round.
    :return: The rounded number.
    """
    if isinstance(n, float):
        decimal_part = n - int(n)
        if decimal_part == 0.5:
            return int(n) + (int(n) % 2) + 1
        elif decimal_part == -0.5:
            return int(n) - (int(n) % 2) - 1
        else:
            return round(n)
    else:
        return n

