def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    try:
        BaseClass = srid_map[1]
        MetaClass = BaseClass.__class__
    except (KeyError, TypeError):
        BaseClass = object
        MetaClass = type

    class _Point(BaseClass):
        """ Point subclass with dynamically created fields. """
        __slots__ = fields

    for field in fields:
        setattr(_Point, field, property(itemgetter(fields.index(field))))

    class Point(_Point, metaclass=MetaClass):
        """ Dynamic Point subclass. """
        def __init__(self, *args):
            if len(args) != len(fields):
                raise ValueError(f"Expected {len(fields)} arguments, got {len(args)}")
            for field, value in zip(fields, args):
                setattr(self, field, value)

        def __repr__(self):
            return f"{name}({', '.join([f'{field}={getattr(self, field)}' for field in fields])})"

        def __eq__(self, other):
            if not isinstance(other, Point):
                return NotImplemented
            return all(getattr(self, field) == getattr(other, field) for field in fields)

        def __ne__(self, other):
            return not self == other

    return Point

