def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """

    normalized_cmd = list(cmd)

    if os.name == 'nt':
        # Check for shebang line
        if normalized_cmd[0].startswith('#!'):
            # Modify the first argument to fix shebang on Windows
            first_arg = normalized_cmd[0]
            if len(first_arg) > 2 and first_arg[2:].startswith('python'):
                normalized_cmd[0] = first_arg[2:]

    return tuple(normalized_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import subprocess

    if os.name == 'nt':
        normalized_cmd = []
        for arg in cmd:
            if arg.startswith('#!'):
                # Replace shebang with the path to python
                python_path = sys.executable
                normalized_arg = python_path + arg[1:]
                normalized_cmd.append(normalized_arg)
            else:
                normalized_cmd.append(arg)
        return tuple(normalized_cmd)
    else:
        return cmd

