import time
from functools import partial, wraps
from contextlib import contextmanager

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def decorator(func):
        cache = {}
        culler = CacheCuller(cache, maxsize, ttl, timer, typed)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else (args, frozenset(kwargs.items()))
            culler.cull()
            if key in cache:
                return cache[key][0]
            result = func(*args, **kwargs)
            cache[key] = (result, timer())
            culler.maybe_cull()
            return result

        @contextmanager
        def put(*args, **kwargs):
            nonlocal cache
            key = (args, tuple(kwargs.items())) if typed else (args, frozenset(kwargs.items()))
            culler.cull()
            yield functools.partial(cache.__setitem__, key)
            result = func(*args, **kwargs)
            cache[key] = (result, timer())
            culler.maybe_cull()

        @contextmanager
        def forget(*args, **kwargs):
            nonlocal cache
            key = (args, tuple(kwargs.items())) if typed else (args, frozenset(kwargs.items()))
            if key in cache:
                del cache[key]

        @contextmanager
        def clear():
            nonlocal cache
            cache.clear()

        wrapper.put = put
        wrapper.forget = forget
        wrapper.clear = clear
        return wrapper

    return decorator

class CacheCuller:
    def __init__(self, cache, maxsize, ttl, timer, typed):
        self.cache = cache
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.typed = typed

    def cull(self):
        now = self.timer()
        for key, (result, ts) in list(self.cache.items()):
            if now - ts > self.ttl:
                del self.cache[key]

    def maybe_cull(self):
        if len(self.cache) > self.maxsize:
            self.cull()
