import time
from functools import wraps

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    class TTLCache:
        def __init__(self, maxsize, ttl, timer):
            self.cache = {}
            self.access_times = {}
            self.ttl = ttl
            self.timer = timer
            self.maxsize = maxsize

        def __getitem__(self, key):
            return self.cache[key]

        def __setitem__(self, key, value):
            self.cache[key] = value
            self.access_times[key] = self.timer()

        def __contains__(self, key):
            return key in self.cache and self.timer() - self.access_times[key] <= self.ttl

        def popitem(self):
            oldest_key = next(iter(self.access_times))
            oldest_time = self.access_times[oldest_key]
            while oldest_time + self.ttl <= self.timer() and len(self.cache) > self.maxsize:
                self.cache.pop(oldest_key)
                self.access_times.pop(oldest_key)
                try:
                    oldest_key = next(iter(self.access_times))
                    oldest_time = self.access_times[oldest_key]
                except StopIteration:
                    break

    def decorator(func):
        memo = TTLCache(maxsize, ttl, timer)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (func.__name__, args, tuple(kwargs.items()))
            if key in memo:
                return memo[key]
            result = func(*args, **kwargs)
            memo[key] = result
            memo.popitem()
            return result

        return wrapper

    return decorator
