def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    import collections

    if not isinstance(maxsize, int) or maxsize < 1:
        raise ValueError('maxsize must be a positive integer')

    def decorator(func):
        cache = collections.defaultdict(collections.OrderedDict)
        access_count = collections.defaultdict(int)
        hit_count = collections.defaultdict(int)
        min_freq = 1

        def get_key(*args, **kwargs):
            if typed:
                return (func, args, tuple(kwargs.items()))
            return (func, tuple(sorted(kwargs.items())) + args)

        def get_item(key):
            item = cache[min_freq].pop(key, None)
            if item:
                access_count[key] += 1
                hit_count[key] += 1
                cache[access_count[key]][key] = item
                min_freq = min(min_freq, access_count[key])
            return item

        def set_item(key, value):
            access_count[key] = 1
            hit_count[key] = 1
            if len(cache[min_freq]) >= maxsize:
                min_freq += 1
            cache[1][key] = value
            min_freq = min(min_freq, 1)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = get_key(*args, **kwargs)
            if key in cache[min_freq]:
                return get_item(key)
            value = func(*args, **kwargs)
            set_item(key, value)
            return value

        wrapper.get_item = get_item
        wrapper.set_item = set_item
        wrapper.access_count = access_count
        wrapper.hit_count = hit_count
        wrapper.cache = cache
        wrapper.min_freq = min_freq
        wrapper.maxsize = maxsize
        wrapper.typed = typed

        return wrapper
    return decorator

