def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections import OrderedDict, defaultdict

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.freq = defaultdict(OrderedDict)

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = args if not self.typed else (type(args), args, type(kwargs), kwargs)
                if key in self.cache:
                    self.freq[self.cache[key]['freq']].move_to_end(key)
                    self.cache[key]['freq'] += 1
                    self.freq[self.cache[key]['freq']].move_to_end(key)
                    return self.cache[key]['result']
                if len(self.cache) >= self.maxsize:
                    lfu_key = next(iter(self.freq[min(self.freq)]))
                    del self.cache[lfu_key]
                    del self.freq[min(self.freq)][lfu_key]
                result = func(*args, **kwargs)
                self.cache[key] = {'freq': 1, 'result': result}
                self.freq[1][key] = None
                return result
            return wrapper

    return LFUCache(maxsize, typed)()
