@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    def format_exception(exc, level):
        if level <= 0:
            return ''
        exc_type, exc_value = exc[0:2]
        return f"{exc_type.__name__}: {exc_value}" + format_exception(exc_value.__traceback__, level - 1)

    def format_path(path, level):
        if level <= 0:
            return ''
        file, line, name, _ = path
        return f"{file}:{line}:{name}" + format_path(path[:-1], level - 1)

    path = traceback.extract_tb(e.__traceback__)
    path_string = format_path(path[:max_path_level], max_path_level)

    if max_level > 0:
        return format_exception((type(e), e, e.__traceback__), max_level)[:-1]
    else:
        return f"{e.__class__.__name__}: {e}" + path_string
