def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    if not classes:
        return []

    def find_min_base(cls):
        if not cls.__bases__ or cls in seen:
            return cls
        seen.add(cls)
        return find_min_base(min(cls.__bases__, key=find_min_base, default=cls))

    seen = set()
    min_bases = set()
    for cls in classes:
        min_base = find_min_base(cls)
        if min_base not in min_bases:
            min_bases.add(min_base)

    return sorted(min_bases, key=classes.index)

