def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    while True:
        new_classes = []
        for cls in classes:
            base = next((b for b in cls.__bases__ if b not in classes), None)
            if base:
                new_classes.append(base)
        if not new_classes:
