        for base in cls.__mro__[:-1]:
            class_tree[base].append(cls)
    minimal_classes = []
    seen = set()
    for cls in classes:
        if cls not in seen:
            minimal_classes.append(cls)
            seen.update(class_tree[cls])
    return minimal_classes

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a dictionary to store the inheritance graph
    inheritance = {cls: set(cls.__bases__) for cls in classes}

    # Identify all leaf nodes (base classes with no subclasses)
    leaves = {cls for cls in classes if not inheritance[cls]}

    # Process the graph and remove redundant bases
    while leaves:
        leaf = leaves.pop()
        for parent in inheritance:
            if leaf in inheritance[parent]:
                inheritance[parent].remove(leaf)
                if not inheritance[parent]:
                    leaves.add(parent)

    # Extract the minimal set of bases
    minimal = [cls for cls in classes if any(leaf not in inheritance[cls] for leaf in leaves)]

    return minimal

