def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

    """
    import re

    class ValidationError(Exception):
        def __init__(self, messages):
            self.messages = messages

    KEY_REGEXP = re.compile(r"^[a-zA-Z0-9_\-]+$")
    VALUE_REGEXP = re.compile(r"^.*$")

    errors = []

    def validate_label(key, value):
        errors.append({"key or value": key if isinstance(value, list) else value, message: "error message"})

    for key, value in labels.items():
        if isinstance(key, list):
            for sub_key in key:
                validate_label(sub_key, value)
        elif not KEY_REGEXP.match(key):
            errors.append({"key": key, "message": "Label key does not match the regex"})
        else:
            if isinstance(value, list):
                for sub_value in value:
                    if not VALUE_REGEXP.match(sub_value):
                        errors.append({"value": sub_value, "message": "expected string or bytes-like object"})
            else:
                if not VALUE_REGEXP.match(value):
                    errors.append({"value": value, "message": "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)
