            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    # Define the regex patterns for valid labels
    key_pattern = re.compile(r'^[a-zA-Z0-9_]+$')
    value_pattern = re.compile(r'^[a-zA-Z0-9_]+$')

    errors = []

    for key, value in labels.items():
        try:
            if isinstance(key, str):
                if not key_pattern.match(key):
                    errors.append({key: "Label key '{}' does not match the regex '^[a-zA-Z0-9_]+$'".format(key)})
            else:
                errors.append({str(key): "expected string or bytes-like object"})
        except (TypeError, re.error):
            errors.append({key: "Label key '{}' is not a string".format(key)})

        try:
            if isinstance(value, str) or isinstance(value, bytes):
                if not value_pattern.match(value):
                    errors.append({key: "Label value '{}' does not match the regex '^[a-zA-Z0-9_]+$'".format(value)})
            elif value is None:
                continue
            else:
                errors.append({key: "expected string or bytes-like object"})
        except (TypeError, re.error):
            errors.append({key: "Label value '{}' is not a string or bytes-like object".format(value)})

        if errors:
            raise ValidationError({"labels": errors})
