def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not app.spec.manifest:
        return {}

    observer_schema = {}
    for resource in app.spec.manifest:
        resource_name = resource["apiVersion"] + "/" + resource["kind"]
        if resource_name in observer_schema:
            continue

        default_observer = {
            "type": "object",
            "properties": {},
            "required": []
        }

        if "metadata" in resource:
            default_observer["properties"]["metadata"] = {
                "type": "object",
                "properties": {
                    "name": {"type": "string"},
                    "namespace": {"type": "string"}
                },
                "required": ["name"]
            }

        if "spec" in resource:
            spec_properties = resource["spec"].get("properties", {})
            default_observer["properties"]["spec"] = {
                "type": "object",
                "properties": spec_properties,
                "additionalProperties": False
            }

        observer_schema[resource_name] = default_observer

    return observer_schema
```

