def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        required_digests = set()
        # Extract required digests from manifest file
        with open(manifest_file, 'r') as file:
            for line in file:
                if 'digest' in line:
                    digest = line.split('=')[1].strip()
                    required_digests.add(digest)

        # Check if required digests are present
        for required_digest in required_digests:
            if required_digest not in digests_used:
                raise ValueError(f"Required digest {required_digest} from {manifest_file} is not present in digests_used.")

        # Check if required digests are used
        unused_digests = digests_used - required_digests
        if unused_digests:
            raise ValueError(f"Digests {unused_digests} from digests_used are not used in {manifest_file}.")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of manifest files to check.
    :param digests_used: Dictionary of digests and their usage status.
    :returns: None if all digests are present and used, otherwise raise an error.
    """
    if not manifest_files or not digests_used:
        raise ValueError("manifest_files and digests_used must not be empty.")

    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as file:
            content = file.read()
            for digest in digests_used:
                if digest not in content:
                    raise ValueError(f"Digest {digest} is not present in {manifest_file}.")
                if not digests_used[digest]:
                    raise ValueError(f"Digest {digest} is not used in {manifest_file}.")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        digests_in_manifest = self.get_digests_from_manifest(manifest_file)
        for digest in digests_in_manifest:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} from {manifest_file} is not used!")
            if digests_used[digest] == 0:
                raise ValueError(f"Digest {digest} from {manifest_file} is present but not used in the manifest!")
        for digest in digests_used:
            if digest not in digests_in_manifest:
                raise ValueError(f"Digest {digest} from {digests_used} is used but not in {manifest_files}!")
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The 'prior' argument must be an instance of InventoryValidator.")

    if set(self.items()) != set(prior.items()):
        raise ValueError("The sets of items in the current inventory and the prior version do not match.")

    for item, value in self.items():
        prior_value = prior.get(item)
        if prior_value is None:
            raise ValueError(f"The prior version does not contain the item: {item}")
        if value != prior_value:
            raise ValueError(f"The value for item {item} does not match in the prior version. "
                             f"Current: {value}, Prior: {prior_value}")
    return True

