        if suppl:
            number = suppl.split('S')[0].strip()
        elif 'S' in issue_content:
            number = issue_content.replace('S', '').strip()
        return number, suppl

    if '-' in issue_content:
        range_values = issue_content.split('-')
        if len(range_values) == 2:
            number = range_values[0].replace('S', '').strip()
            suppl = range_values[1].replace('S', '').strip()
            return number, suppl

    if 'SUPPL' in issue_content:
        suppl = issue_content.replace('SUPPL', '').strip()
        if suppl:
            number = suppl.split('S')[0].strip()
        elif 'S' in issue_content:
            number = issue_content.replace('S', '').strip()
        return number, suppl

    if 'SUPL' in issue_content:
        suppl = issue_content.replace('SUPL', '').strip()
        if suppl:
            number = suppl.split('S')[0].strip()
        elif 'S' in issue_content:
            number = issue_content.replace('S', '').strip()
        return number, suppl

    return number, suppl

