def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extract the values of number and suppl from the content of <issue>xxxx</issue>.

    :param issue: The content of the <issue> element to extract number and suppl from.
    :returns: A tuple containing the extracted number and suppl, or None if no valid values are found.
    """
    # Regular expression to match the number and suppl values
    pattern = r'(\d+(?:[-\d]+)?(?:Suppl(?:[.\s]?\d+)?)?(?:spe(?:[.\s]?\d+)?)?)'
    matches = re.findall(pattern, issue, re.IGNORECASE)

    if not matches:
        return None

    number = None
    suppl = None

    for match in matches:
        match = match.strip().lower()
        if match.startswith('spe'):
            suppl = match
        elif match.startswith('suppl'):
            suppl = match
        else:
            try:
                supp_num = int(match.split('suppl')[1].strip())
                suppl = f'suppl {supp_num}'
            except IndexError:
                number = match
            except ValueError:
                pass

    if number and suppl:
        return number, suppl
    elif number:
        return number, None
    elif suppl:
        return None, suppl
    else:
        return None
