def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def simplify_expression(expr):
        if expr in ('A', 'B'):
            return expr
        left, operator, right = expr.split()
        if operator == '&':
            if left == right:
                return left
            elif left == '~' + right:
                return right
        elif operator == '|':
            if left == right:
                return left
            elif left == '~' + right:
                return left
        return expr

    return [simplify_expression(expr) for expr in args]
