def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for expr in args:
        if isinstance(expr, tuple):
            if expr[0] == 'and':
                if expr[1][0] == 'or' and expr[1][1] == expr[0]:
                    new_args.append(expr[0])
                elif expr[1][0] == 'and' and expr[1][1] == expr[0]:
                    new_args.append(expr[0])
            elif expr[0] == 'or':
                if expr[1][0] == 'and' and expr[1][1] == expr[0]:
                    new_args.append(expr[0])
                elif expr[1][0] == 'or' and expr[1][1] == expr[0]:
                    new_args.append(expr[0])
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def simplify(expr):
        if isinstance(expr, tuple):
            op, args = expr[0], expr[1:]
            if op == 'and':
                a, b = simplify(args[0]), simplify(args[1])
                if a == b:
                    return a
                elif a == ('or', b) or b == ('or', a):
                    return a
            elif op == 'or':
                a, b = simplify(args[0]), simplify(args[1])
                if a == b:
                    return a
                elif a == ('and', b) or b == ('and', a):
                    return a
        return expr

    return [simplify(expr) for expr in args]

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption: A & (A | B) = A, A | (A & B) = A

    Negative absorption: A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if expr.is_binary() and expr.left.is_binary() and expr.right.is_binary():
            if expr.op == 'And':
                if expr.left.op == 'Or':
                    if expr.left.left == expr.right:
                        return expr.left.left
                    if expr.left.right == expr.right:
                        return expr.left.right
                elif expr.right.op == 'Or':
                    if expr.right.left == expr.left:
                        return expr.right.left
                    if expr.right.right == expr.left:
                        return expr.right.right
            elif expr.op == 'Or':
                if expr.left.op == 'And':
                    if expr.left.left == expr.right:
                        return expr.left.left
                    if expr.left.right == expr.right:
                        return expr.left.right
                elif expr.right.op == 'And':
                    if expr.right.left == expr.left:
                        return expr.right.left
                    if expr.right.right == expr.left:
                        return expr.right.right
        return expr

    def apply_negative_absorption(expr):
        if expr.is_binary() and expr.left.is_binary() and expr.right.is_binary():
            if expr.op == 'And':
                if expr.left.op == 'Not' and expr.left.child == expr.right:
                    return expr.right
            elif expr.op == 'Or':
                if expr.left.op == 'Not' and expr.left.child == expr.right:
                    return expr.right
        return expr

    result = []
    for expr in args:
        expr = apply_absorption(expr)
        expr = apply_negative_absorption(expr)
        result.append(expr)

    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        if hasattr(self, '_handlers'):
            if hook in self._handlers:
                self._handlers[hook].append(func)
            else:
                self._handlers[hook] = [func]
        else:
            self._handlers = {hook: [func]}
        return func
    return decorator

from dateutil.relativedelta import relativedelta

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    while self.days >= 1:
        self += relativedelta(days=1)
    while self.days <= -1:
        self -= relativedelta(days=1)
    while self.hours >= 24:
        self += relativedelta(hours=24)
    while self.hours <= -24:
        self -= relativedelta(hours=24)
    while self.minutes >= 60:
        self += relativedelta(minutes=60)
    while self.minutes <= -60:
        self -= relativedelta(minutes=60)
    while self.seconds >= 60:
        self += relativedelta(seconds=60)
    while self.seconds <= -60:
        self -= relativedelta(seconds=60)
    while self.microseconds >= 1000000:
        self += relativedelta(microseconds=1000000)
    while self.microseconds <= -1000000:
        self -= relativedelta(microseconds=1000000)
    return self

