    root_inventory = {}
    digests_record = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory')
        if not os.path.exists(inventory_path):
            raise ValueError(f"Inventory not found for version: {version_dir}")

        with open(inventory_path, 'r') as h:
            # Assuming inventory is a simple key-value mapping for now
            inventory = json.load(h)

        for key, value in inventory.items():
            if key in root_inventory:
                if root_inventory[key] != value:
                    digests_record[key] = value
            else:
                root_inventory[key] = value

    # Check content digests against root inventory
    for digest_key, digest_value in digests_record.items():
        root_value = root_inventory.get(digest_key)
        if root_value != digest_value:
            raise ValueError(f"Digest mismatch for key: {digest_key}")
    return True

