def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        raise ValueError('No version directories provided')

    root_inventory = {}

    for version_dir in version_dirs:
        if not version_dir.isdigit():
            raise ValueError(f'Invalid version directory: {version_dir}')

        inventory_path = os.path.join(self.inv_root, version_dir, 'inventory.json')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f'Inventory file not found for version directory: {version_dir}')

        with open(inventory_path, 'r') as f:
            inventory = json.load(f)

        if not isinstance(inventory, dict):
            raise ValueError(f'Invalid inventory format for version directory: {version_dir}')

        if version_dir == '1':
            root_inventory = inventory
        else:
            for item, item_inventory in root_inventory.items():
                if item not in inventory:
                    raise ValueError(f'Missing item {item} in version {version_dir} inventory')
                for sub_item, sub_item_inventory in item_inventory.items():
                    if sub_item not in inventory[item]:
                        raise ValueError(f'Missing sub-item {sub_item} in version {version_dir} inventory')

    return root_inventory

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os

        # Check if the path exists
        if not os.path.exists(path):
            return "Path does not exist"

        # Check if the path is a file
        if os.path.isfile(path):
            return "file"

        # Check if the path is a directory
        if os.path.isdir(path):
            namaste_file_path = os.path.join(path, "0=*")

            # Check if the Namaste file exists in the directory
            if os.path.exists(namaste_file_path):
                if "storage-root" in open(namaste_file_path).read():
                    return "root"
                elif "object-root" in open(namaste_file_path).read():
                    return "object"
                else:
                    return "other"
            else:
                return "Namaste file not found"
        else:
            return "Not a directory or file"
    except Exception as e:
        return f"Error occurred: {e}"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
    except ImportError:
        return "Error: Unable to import os module."

    if not os.path.exists(path):
        return "Error: Path does not exist."

    if os.path.isfile(path):
        return 'file'

    namaste_files = [f for f in os.listdir(path) if f.startswith('0=')]

    if not namaste_files:
        return "Error: No Namaste files found."

    for file in namaste_files:
        with open(os.path.join(path, file), 'r') as f:
            content = f.read().strip()
            if content == 'storage':
                return 'root'
            elif content == 'object':
                return 'object'
            else:
                return f"Unknown type: {content}"

