def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    from argparse import ArgumentParser, _SubParsersAction
    import sys

    parser = ArgumentParser(add_help=False)
    subparsers_action = _SubParsersAction(name="subparser", dest="subparser")
    parser._action_groups.append(subparsers_action)

    def add_subparser(subparser_name, help_text):
        subparser = subparsers_action.add_parser(subparser_name, help=help_text)
        def subparser_parser(*args, **kwargs):
            return subparser.parse_args(args, **kwargs)
        subparser_parser.__doc__ = f"Parse arguments for {subparser_name}"
        return subparser_parser

    def parse_args(*args):
        return parser.parse_args(args)

    global_args, subparser_args = parse_args(unparsed_arguments)

    subparser_name = getattr(global_args, "subparser", None)
    if subparser_name and subparser_name in subparsers_action.choices:
        subparser_func = subparsers_action.choices[subparser_name]
        return {subparser_name: subparser_func(*subparser_args)}
    else:
        return {"global": global_args}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        subparser_args = []
        while remaining_arguments and remaining_arguments[0] != subparser_name:
            subparser_args.append(remaining_arguments.pop(0))
        if remaining_arguments:
            subparser_args.append(remaining_arguments.pop(0))  # Consume the subparser name
        if subparser_args:
            try:
                ns, remaining = parser.parse_known_args(subparser_args)
                parsed_results[subparser_name] = ns
                remaining_arguments.extend(remaining)
            except Exception as e:
                print(f"Error parsing arguments for subparser '{subparser_name}': {e}")
                remaining_arguments.extend(subparser_args)

    return parsed_results, remaining_arguments

