    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """

    from ruamel.yaml.nodes import MappingNode

    merged = {}

    def merge_recursive(key, lhs, rhs):
        if isinstance(lhs, MappingNode) and isinstance(rhs, MappingNode):
            merged_dict = lhs.value + rhs.value
            for item in merged_dict:
                new_key = item[0]
                lhs_node = next((node for node in lhs.value if node[0] == new_key), None)
                rhs_node = next((node for node in rhs.value if node[0] == new_key), None)
                if lhs_node and rhs_node:
                    merge_recursive(new_key, lhs_node[1], rhs_node[1])
                elif rhs_node:
                    new_item = (item[0], rhs_node[1])
                    merged[key].append(new_item)
        else:
            merged[key].append(rhs)

    for key, value in nodes:
        if key.value not in merged:
            merged[key.value] = [value]
        else:
            merge_recursive(key.value, merged[key.value][-1], value)

    return [(key_node, value_node) for key_node, value_node in merged.items()]
```

def deep_merge_nodes(nodes):
    result = {}
    for key_node, value_node in nodes:
        if key_node.value in result:
            if isinstance(result[key_node.value], ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                result[key_node.value] = deep_merge_nodes(list(zip(result[key_node.value].value, value_node.value)))
            else:
                result[key_node.value] = value_node
        else:
            result[key_node.value] = value_node
    return [(key_node, value_node) for key_node, value_node in result.items()]

