def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    return seen

def subclasses(cls):
    """Return all subclasses of a class, recursively"""

    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop()
        if c not in seen:
            seen.add(c)
            queue.extend(c.__subclasses__())

    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    inverse_alphabet = {char: idx for idx, char in enumerate(alphabet)}
    result = 0
    zero_index = inverse_alphabet.get("0")
    if zero_index is None:
        raise ValueError("Alphabet must contain the character '0'")
    for char in string:
        if char not in inverse_alphabet:
            raise ValueError(f"Invalid character '{char}' in string")
        result = result * base + inverse_alphabet[char]
    return result

