        import os
        platform = 1 if os.name == 'posix' else 0

    if platform == 0:
        # Windows/CMD
        return re.findall(r'[^\\"]+|"[^"]*"', s)
    elif platform == 1:
        # POSIX
        return re.findall(r'[^\\\'"]+|\'[^\']*\'|"[^"]*"', s)
    else:
        raise ValueError("Invalid platform value")
