def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """

    if not os.path.exists(archive_path):
        raise ValueError(f"The archive {archive_path} does not exist.")

    if isinstance(tmp_path, str):
        tmp_path = Path(tmp_path)

    if not tmp_path.is_dir():
        raise ValueError(f"The provided path {tmp_path} is not a directory.")

    if filename is None:
        filename = archive_path.split(os.path.sep)[-1]

    extract_to = tmp_path / filename.rsplit('.', 1)[0]
    extract_to.mkdir(exist_ok=True, parents=True)

    try:
        command = ['tar', '--directory', str(extract_to), '-xzf', archive_path]
        subprocess.run(command, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract {archive_path}: {e}")

    repo_url = f"file://{os.path.abspath(extract_to)}"
    return repo_url

