import subprocess
from typing import Optional, Union
from pathlib import PosixPath

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive does not exist: {archive_path}")

    if not os.path.exists(tmp_path):
        os.makedirs(tmp_path)

    if filename is None:
        _, filename = os.path.split(archive_path)

    temp_extract_path = os.path.join(tmp_path, filename.split('.')[0])
    if not os.path.exists(temp_extract_path):
        os.makedirs(temp_extract_path)

    try:
        if archive_path.endswith('.tar.gz'):
            subprocess.check_call(['tar', '-zxvf', archive_path, '-C', temp_extract_path])
        elif archive_path.endswith('.tar.bz2'):
            subprocess.check_call(['tar', '-xjvf', archive_path, '-C', temp_extract_path])
        else:
            raise ValueError(f"Unsupported archive type: {archive_path}")
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to extract archive: {e}")

    return f"file://{temp_extract_path}"
