    def git(args, error_message, cwd=None, **error_kwargs):
        output, status = subprocess.Popen(args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()
        if status != 0:
            error_kwargs['output'] = output.decode()
            error_kwargs['directory'] = cwd if cwd else 'n/a'
            raise Exception(error_message, **error_kwargs)
        return output.decode().splitlines()

    try:
        ignored_files = git(['git', 'ls-files', '--exclude-standard'], 'Failed to find ignored files')
        sorted_ignored_files = sorted([file for file in ignored_files if file in ignored])
        return ','.join(sorted_ignored_files)
    except Exception as e:
        print(f"An error occurred: {e}")
        return ''

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None
    frequency = frequency.replace(" ", "")
    if not frequency[-1].isdigit():
        raise ValueError("Invalid frequency format")
    number = int(frequency[:-1])
    unit = frequency[-1].lower()
    if unit == "s":
        return datetime.timedelta(seconds=number)
    elif unit == "m":
        return datetime.timedelta(minutes=number)
    elif unit == "h":
        return datetime.timedelta(hours=number)
    elif unit == "d":
        return datetime.timedelta(days=number)
    elif unit == "w":
        return datetime.timedelta(weeks=number)
    else:
        raise ValueError("Invalid unit of time")

