def make_find_paths(find_paths):
    'Given a sequence of path fragments or patterns as passed to `--find`, transform all path fragments into glob patterns. Pass through existing patterns untouched.'

    glob_pattern = re.compile(r'^\S+:')

    transformed_paths = []
    for path in find_paths:
        if glob_pattern.match(path):
            transformed_paths.append(path)
        else:
            transformed_paths.append(f'sh:**/*{path}*/**')

    return transformed_paths

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    if not overwrite and os.path.isfile(config_filename):
        raise FileExistsError(f"File {config_filename} already exists and overwrite is set to False.")

    try:
        config_dir = os.path.dirname(config_filename)
        if config_dir:
            os.makedirs(config_dir, exist_ok=True)

        with open(config_filename, 'w', mode=mode) as file:
            file.write(rendered_config)
    except IOError as e:
        raise IOError(f"Failed to write configuration to {config_filename}: {e}")

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    config_filename = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_filename):
        return
    else:
        try:
            config_filename_dir_name = os.path.dirname(config_filename)
            os.makedirs(config_filename_dir_name)
        except OSError:
            if not os.path.isdir(config_filename_dir_name):
                raise
        with open(config_filename, "w", mode=mode) as f:
            f.write(rendered_config)

def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    if not isinstance(script, (list, str)):
        raise ValueError("script must be a list of strings or a string")

    if isinstance(script, list):
        script = [textwrap.dedent(s).strip() for s in script]
        script = [s for s in script if s]

    return separator.join(filter(None, script))

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    try:
        name, default = matcher
    except ValueError:
        raise ValueError("_resolve_string requires a tuple containing the environment variable name and an optional default value.")

    value = os.environ.get(name, default)
    if value is None:
        raise EnvironmentError(f"Environment variable '{name}' not found and no default value provided.")

    return value

