                output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, cwd=cwd, env=env, text=True)
                if not hide_stderr and verbose:
                    print(output, end='')
                results.append(output)
            except subprocess.CalledProcessError as e:
                msg = f"Error running command {command}: {e.output}"
                if not hide_stderr and verbose:
                    print(msg, end='')
                results.append(msg)
    except TypeError as e:
        raise TypeError("commands must be a list of strings and args must be a list of strings") from e

