                if resolve_env:
                    config = resolve_environment_variables(config)
                config_dict[filename] = config
        except FileNotFoundError:
            logger.warning(f"Configuration file {filename} not found. Skipping.")
        except (toml.TomlDecodeError, yaml.YAMLError) as e:
            logger.error(f"Error parsing configuration file {filename}: {e}")
            log_records.append(logging.LogRecord(logging.ERROR, f"Error parsing configuration file {filename}: {e}", exc_info=True))
        except Exception as e:
            logger.error(f"Unexpected error while processing configuration file {filename}: {e}")
            log_records.append(logging.LogRecord(logging.ERROR, f"Unexpected error while processing configuration file {filename}: {e}", exc_info=True))

    for filename in config_filenames:
        load_and_validate_config(filename)

    return config_dict, log_records
