class Bookmarks:
    @classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """

        if not all(isinstance(val, str) for val in values):
            raise ValueError("All elements in values must be strings")

        bookmarks = []
        for value in values:
            # Assuming the raw bookmark string format is known and can be parsed here
            # For example, splitting by commas or semicolons
            bookmark_items = value.split(',')
            for item in bookmark_items:
                bookmarks.append(item.strip())

        return cls(bookmarks)
