def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    for base in bases:
        base_mc = getattr(base, '__metaclass__', None)
        if base_mc:
            return base_mc

    if explicit_mc:
        return explicit_mc

    for base in bases:
        base_class = getattr(base, '__class__', type)
        for mro_cls in base_class.mro():
            if hasattr(mro_cls, '__metaclass__'):
                return mro_cls.__metaclass__

    return type

