    if explicit_mc is not None:
        return explicit_mc

    # Iterate through bases to find metaclass
    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    # Fallback to Python 3's __class__ attribute
    for base in bases:
