def process_text_links(text):
    """
    Process links in text, adding some attributes and linkifying textual links.

    :param string text: The text to process.
    :returns: The processed text with added attributes and linkified links.
    """
    def maybe_add_link(url, text):
        return '<a target="_blank" href="{}">{}</a>'.format(url, text) if url else text

    def linkify_url(m):
        url = m.group(0)
        return maybe_add_link(url, url)

    def linkify_textual_link(m):
        link_text = m.group(0)
        if link_text.startswith('http://') or link_text.startswith('https://'):
            return linkify_url(m)
        else:
            return maybe_add_link('/link/{0}'.format(link_text), link_text)

    import re
    text = re.sub(r'https?://[^\s]+', linkify_url, text)
    text = re.sub(r'\b\w+\b', linkify_textual_link, text)
    return text
```

