def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try parsing as JSON
        data = json.loads(document)
        if "links" in data:
            result = {}
            for link in data["links"]:
                if "rel" in link and "href" in link:
                    result.setdefault(link["rel"], []).append(link["href"])
            return result
    except json.JSONDecodeError:
        # If parsing as JSON fails, try parsing as XRD
        try:
            root = ET.fromstring(document)
            result = {}
            for link in root.findall(".//{%s}Link" % "http://salmon-protocol.org/ns/network"):
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    result.setdefault(rel, []).append(href)
            return result
        except ET.ParseError:
            # If parsing as XRD fails, return None
            return None
