def list_of_file_names(settings_dirs, spec_option):
    """
    Create a list of file names based on the given settings directories and specification option.

    Args:
        settings_dirs (list): List of directories containing settings files.
        spec_option (str): Specification option for file naming.

    Returns:
        list: List of fully qualified file names.

    Raises:
        ValueError: If settings_dirs is not a list or spec_option is not a string.
        FileNotFoundError: If any directory in settings_dirs does not exist.
    """
    if not isinstance(settings_dirs, list) or not all(isinstance(d, str) for d in settings_dirs):
        raise ValueError("settings_dirs should be a list of strings")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option should be a string")

    file_names = []
    for directory in settings_dirs:
        if not os.path.exists(directory):
            raise FileNotFoundError(f"Directory {directory} does not exist")
        try:
            for root, _, files in os.walk(directory):
                for file in files:
                    if file.endswith(f".{spec_option}"):
                        file_names.append(os.path.join(root, file))
        except OSError as e:
            print(f"Error processing directory {directory}: {e}")

    return sorted(file_names)

