def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if self._condition_matches(condition, args, command_name):
                matched_args.append(option['name'])
    return matched_args

def _condition_matches(self, condition, args, command_name):
    """Check if the condition is met.

    :param condition: the condition dictionary.
    :param args: the received input arguments
    :param command_name: the command name.
    :return: bool, True if the condition is met, otherwise False.
    """
    for key, value in condition.items():
        if key == 'args':
            if not any(args.get(arg) == value for arg in value):
                return False
        elif key == 'option':
            if args.get(key, None) != value:
                return False
        elif key == 'empty':
            if args.get(key, False):
                return False
        elif key == 'present':
            if not args.get(key, False):
                return False
    return True

