@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """ Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not vars_dict:
        if extra_vars:
            return {**extra_vars}
        return {}

    if extra_vars is None:
        return vars_dict

    merged_dict = vars_dict.copy()
    for extra_var in extra_vars:
        if isinstance(extra_var, dict):
            merged_dict.update(extra_var)
        else:
            raise ValueError("extra_vars should be a list of dictionaries")

    return merged_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars

    :returns: Extended dictionary
    :rtype: dict
    """
    if extra_vars is None:
        return vars_dict

    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or tuple")

    extended_vars = vars_dict.copy()
    for extra_var in extra_vars:
        if isinstance(extra_var, dict):
            extended_vars.update(extra_var)
        elif isinstance(extra_var, list):
            extended_vars.extend(extra_var)
        else:
            extended_vars.append(extra_var)

    return extended_vars

