        'ospd': {'port': int, 'timeout': float}
    }

    # Get the expected types for the given parser
    expected_types = type_mapping.get(parser_name, {})

    # Convert values to expected types
    for key, value in values_dict.items():
        if key in expected_types:
            try:
                values_dict[key] = expected_types[key](value)
            except ValueError:
                # Handle the case where the conversion fails
                print(f"Failed to convert {key} to {expected_types[key]}. Using default value.")
                values_dict[key] = expected_types[key](None)  # Set to default value of the type

