def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param subparser: the subparser object to extend.
    """
    if not root_subparsers:
        raise ValueError("root_subparsers must be provided")

    for command, subcommand_parser in self.subcommands.items():
        subcommand_parser.set_defaults(func=self._run_command, command=command)
        root_subparsers.add_parser(command, help=subcommand_parser.description, parents=[subcommand_parser])
